import { Button, Spinner } from "@heroui/react";
import type { ComponentProps, ReactNode } from "react";

type HeroButtonProps = ComponentProps<typeof Button>;

interface AsyncButtonProps extends Omit<
  HeroButtonProps,
  "isPending" | "isDisabled" | "children"
> {
  /** Whether the async operation is in progress. Shows spinner and disables the button. */
  readonly isLoading: boolean;
  /** Button label or content shown when not loading. */
  readonly children: ReactNode;
  /** Optional label shown while loading. Defaults to children. */
  readonly loadingText?: string;
  /**
   * Whether the button should be disabled.
   */
  readonly isDisabled?: boolean;
}

/**
 * A wrapper around HeroUI's Button that automatically shows a spinner
 * and disables interaction while an async operation is in progress.
 *
 * Usage:
 * ```tsx
 * <AsyncButton isLoading={loading} variant="primary" type="submit">
 *   Guardar
 * </AsyncButton>
 * ```
 */
export function AsyncButton({
  isLoading,
  children,
  loadingText,
  ...rest
}: AsyncButtonProps) {
  return (
    <Button
      {...rest}
      isDisabled={isLoading || rest.isDisabled}
      isPending={isLoading}
    >
      {({ isPending }: { readonly isPending: boolean }) => (
        <>
          {isPending ? <Spinner color="current" size="sm" /> : null}
          {isPending && loadingText ? loadingText : children}
        </>
      )}
    </Button>
  );
}

import { Button } from "@heroui/react";
import { useNavigate } from "react-router";
import type { DispenseResponse } from "../../types/DispenseResponse";
import type { TableColumnWithFilters } from "../../types/TableColumnWithFilters";
import { formatDateTime } from "../../utils/dateFormatter";

function DispenseButton({ data }: { readonly data: DispenseResponse }) {
  const navigate = useNavigate();
  return (
    <Button
      isIconOnly
      aria-label="Ver detalle"
      size="sm"
      variant="primary"
      onClick={() => navigate(`/dispense/${data.id}`)}
    >
      <i className="bi bi-eye" />
    </Button>
  );
}

export const DispenseResponseColumns: TableColumnWithFilters<DispenseResponse>[] =
  [
    {
      id: "id",
      name: "ID",
      selector: (data) => data.id ?? "",
      sortable: true,
      wrap: true,
      omit: false,
      hasFilter: true,
      filterField: (value) => (value ? `Id:eq:${value}` : ""),
    },
    {
      id: "prescriptionId",
      name: "Receta ID",
      selector: (data) => data.prescriptionId ?? "",
      sortable: true,
      wrap: true,
      omit: false,
      hasFilter: true,
      filterField: (value) => (value ? `PrescriptionId:eq:${value}` : ""),
    },
    {
      id: "pharmacistId",
      name: "Farmacéutico ID",
      selector: (data) => data.pharmacistId ?? "",
      sortable: true,
      wrap: true,
      omit: false,
      hasFilter: false,
    },
    {
      id: "dispenseDate",
      name: "Fecha de Despacho",
      selector: (data) => formatDateTime(data.createdAt),
      sortable: true,
      wrap: true,
      omit: false,
      hasFilter: false,
    },
    {
      id: "totalAmount",
      name: "Total",
      selector: (data) => `Q ${data.totalAmount?.toFixed(2) ?? "0.00"}`,
      sortable: true,
      wrap: true,
      omit: false,
      hasFilter: false,
    },
    {
      id: "state",
      name: "Estado",
      selector: (data) => (data.state === 1 ? "Activo" : "Inactivo"),
      sortable: true,
      wrap: true,
      omit: false,
      hasFilter: false,
    },
    {
      id: "actions",
      name: "Acciones",
      maxWidth: "100px",
      center: true,
      button: true,
      cell: (data) => <DispenseButton data={data} />,
    },
  ];

import type { InventoryMovementResponse } from "../../types/InventoryMovementResponse";
import { MovementTypeLabels } from "../../types/InventoryMovementResponse";
import type { TableColumnWithFilters } from "../../types/TableColumnWithFilters";
import { formatDateTime } from "../../utils/dateFormatter";
import { InventoryMovementButton } from "../button/InventoryMovementButton";

function MovementTypeBadge({
  movementType,
}: {
  readonly movementType: number;
}) {
  const info = MovementTypeLabels[movementType] ?? {
    label: "Desconocido",
    color: "bg-gray-100 text-gray-800",
  };
  return (
    <span
      className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${info.color}`}
    >
      {info.label}
    </span>
  );
}

export const InventoryMovementResponseColumns: TableColumnWithFilters<InventoryMovementResponse>[] =
