    {
      id: "createdAt",
      name: "Fecha/Hora",
      selector: (data) => formatDateTime(data.createdAt),
      sortable: true,
      wrap: true,
      omit: false,
      hasFilter: false,
    },
    {
      id: "movementType",
      name: "Tipo",
      cell: (data) => <MovementTypeBadge movementType={data.movementType} />,
      sortable: true,
      wrap: true,
      omit: false,
      hasFilter: true,
      filterField: (value) => (value ? `MovementType:eq:${value}` : ""),
    },
    {
      id: "medicine",
      name: "Medicamento",
      selector: (data) => data.medicine?.name ?? String(data.medicineId),
      sortable: true,
      wrap: true,
      omit: false,
      hasFilter: true,
      filterField: (value) => (value ? `Medicine.Name:like:${value}` : ""),
    },
    {
      id: "branch",
      name: "Sucursal",
      selector: (data) => data.branch?.name ?? String(data.branchId),
      sortable: true,
      wrap: true,
      omit: false,
      hasFilter: true,
      filterField: (value) => (value ? `Branch.Name:like:${value}` : ""),
    },
    {
      id: "quantity",
      name: "Cantidad",
      selector: (data) => data.quantity ?? 0,
      sortable: true,
      wrap: true,
      omit: false,
      hasFilter: false,
    },
    {
      id: "previousStock",
      name: "Stock Anterior",
      selector: (data) => data.previousStock ?? 0,
      sortable: true,
      wrap: true,
      omit: false,
      hasFilter: false,
    },
    {
      id: "newStock",
      name: "Stock Nuevo",
      selector: (data) => data.newStock ?? 0,
      sortable: true,
      wrap: true,
      omit: false,
      hasFilter: false,
    },
    {
      id: "totalCost",
      name: "Costo",
      selector: (data) => `Q ${(data.totalCost ?? 0).toFixed(2)}`,
      sortable: true,
      wrap: true,
      omit: false,
      hasFilter: false,
    },
    {
      id: "referenceNumber",
      name: "Referencia",
      selector: (data) => data.referenceNumber ?? "—",
      sortable: false,
      wrap: true,
      omit: false,
      hasFilter: true,
      filterField: (value) => (value ? `ReferenceNumber:like:${value}` : ""),
    },
    {
      id: "user",
      name: "Usuario",
      selector: (data) => data.user?.name ?? String(data.userId),
      sortable: true,
      wrap: true,
      omit: false,
      hasFilter: true,
      filterField: (value) => (value ? `User.Name:like:${value}` : ""),
    },
    {
      id: "actions",
      name: "Acciones",
      maxWidth: "100px",
      center: true,
      button: true,
      cell: (data) => <InventoryMovementButton data={data} />,
    },
  ];

import { Button } from "@heroui/react";
import type { OperationResponse } from "../../types/OperationResponse";
import type { TableColumnWithFilters } from "../../types/TableColumnWithFilters";

export interface OperationWithAssignment extends OperationResponse {
  assigned: boolean;
  rolOperationId?: number;
}

export function getRolOperationColumns(
  onToggle: (op: OperationWithAssignment) => void,
): TableColumnWithFilters<OperationWithAssignment>[] {
  return [
    {
      id: "id",
      name: "ID",
      selector: (data) => data.id ?? "",
      sortable: true,
      wrap: true,
      omit: false,
    },
    {
      id: "name",
      name: "Nombre",
      selector: (data) => data.name ?? "",
      sortable: true,
      wrap: true,
      omit: false,
    },
    {
      id: "path",
      name: "Ruta",
      selector: (data) => data.path ?? "",
      sortable: true,
      wrap: true,
      omit: false,
    },
    {
      id: "httpMethod",
      name: "Método HTTP",
      selector: (data) =>
        (data as OperationWithAssignment & { httpMethod?: string })
          .httpMethod ?? "",
      sortable: true,
      wrap: true,
      omit: false,
    },
    {
      id: "assigned",
      name: "Estado",
      center: true,
      cell: (data) =>
        data.assigned ? (
          <span className="px-2 py-1 rounded text-xs font-semibold bg-green-100 text-green-800">
            Asignado
          </span>
        ) : (
          <span className="px-2 py-1 rounded text-xs font-semibold bg-gray-100 text-gray-600">
            No asignado
          </span>
        ),
    },
    {
      id: "actions",
      name: "Acciones",
      center: true,
      button: true,
      cell: (data) => (
        <Button
          size="sm"
          variant={data.assigned ? "danger" : "primary"}
          onClick={() => onToggle(data)}
        >
          {data.assigned ? "Quitar" : "Asignar"}
        </Button>
      ),
    },
  ];
}

import { useCallback, useState } from "react";
import { useSearchParams } from "react-router";
import type { SingleValue } from "react-select";
import { useReservationTimer } from "../../hooks/useReservationTimer";
import { getBranches } from "../../services/branchService";
import { getSpecialties } from "../../services/specialtyService";
import { getUsers } from "../../services/userService";
import type { ApiResponse } from "../../types/ApiResponse";
import type {
  AppointmentRequest,
  AppointmentResponse,
} from "../../types/AppointmentResponse";
import type { BranchResponse } from "../../types/BranchResponse";
import type { SpecialtyResponse } from "../../types/SpecialtyResponse";
import type { UserResponse } from "../../types/UserResponse";
import type { ValidationFailure } from "../../types/ValidationFailure";
import { formatDateTimeLong } from "../../utils/dateFormatter";
import { AsyncButton } from "../button/AsyncButton";
import { Response } from "../messages/Response";
import { DynamicCalendar } from "../portal/DynamicCalendar";
import { CatalogueSelect } from "../select/CatalogueSelect";
import { CountdownTimer } from "../shared/CountdownTimer";
import { StepForm } from "../shared/StepForm";

// ─── Edit-mode imports (kept for the simple single-step edit flow) ───────────
import { FieldError, Form, Input, Label, TextField } from "@heroui/react";
import { useCallback as useCallbackEdit, type ChangeEvent } from "react";
import { useNavigate } from "react-router";
import { useForm } from "../../hooks/useForm";
import { getAppointmentStatuses } from "../../services/appointmentStatusService";
import type { AppointmentStatusResponse } from "../../types/AppointmentStatusResponse";
import { validateAppointment } from "../../validations/appointmentValidation";
import { OptionsSelect, type OptionValue } from "../select/OptionsSelect";

// ─── Shared ──────────────────────────────────────────────────────────────────

interface AppointmentFormProps {
  readonly type: "create" | "edit";
  readonly initialForm: AppointmentRequest;
  readonly onSubmit: (
    form: AppointmentRequest,
  ) => Promise<ApiResponse<unknown | ValidationFailure[]>>;
  readonly onSuccess?: (appointmentId: number) => void;
}

// ─── Document validation helper ──────────────────────────────────────────────

const validateDocument = (file: File): string | null => {
  if (file.type !== "application/pdf") return "Solo se permiten archivos PDF";
  if (file.size > 2097152) return "El archivo no puede superar 2MB";
  return null;
};

// ─── Step labels ─────────────────────────────────────────────────────────────

const STEP_LABELS = [
  "Especialidad y Sucursal",
  "Médico y Fecha",
  "Motivo y Documento",
  "Confirmación",
];

// ─── Multi-step create form state ────────────────────────────────────────────

interface CreateFormState {
  specialtyId: string | null;
  specialtyLabel: string;
  branchId: string | null;
  branchLabel: string;
  doctorId: string | null;
  doctorLabel: string;
  appointmentDate: string;
  reason: string;
  document: File | null;
  documentError: string | null;
}

const initialCreateState: CreateFormState = {
  specialtyId: null,
  specialtyLabel: "",
  branchId: null,
  branchLabel: "",
  doctorId: null,
  doctorLabel: "",
  appointmentDate: "",
  reason: "",
  document: null,
  documentError: null,
};

// ─── Confirmation step (step 4) ──────────────────────────────────────────────

interface ConfirmationStepProps {
  readonly state: CreateFormState;
  readonly onExpiry: () => void;
  readonly onSubmit: () => Promise<void>;
  readonly loading: boolean;
  readonly submitError: string | null;
}

function ConfirmationStep({
  state,
  onExpiry,
  onSubmit,
  loading,
  submitError,
}: ConfirmationStepProps) {
  const { remaining, isExpired } = useReservationTimer(5, onExpiry);

  if (isExpired) {
    return (
      <div className="flex flex-col items-center gap-4 py-8 text-center">
        <p className="text-red-600 font-semibold text-lg">
          El tiempo de reserva ha expirado. Por favor, vuelva a intentarlo.
        </p>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-6">
      <div className="flex justify-center">
        <CountdownTimer label="Tiempo para confirmar" remaining={remaining} />
      </div>

      <div className="rounded-lg border border-gray-200 bg-gray-50 p-4 flex flex-col gap-3">
        <h3 className="font-semibold text-gray-700 text-sm uppercase tracking-wide">
          Resumen de la cita
        </h3>
        <SummaryRow label="Especialidad" value={state.specialtyLabel} />
        <SummaryRow label="Sucursal" value={state.branchLabel} />
        <SummaryRow label="Médico" value={state.doctorLabel} />
        <SummaryRow
          label="Fecha y hora"
          value={
            state.appointmentDate
              ? formatDateTimeLong(state.appointmentDate)
              : "—"
          }
        />
        <SummaryRow label="Motivo" value={state.reason} />
        {state.document ? (
          <SummaryRow label="Documento" value={state.document.name} />
        ) : null}
      </div>

      {submitError ? (
        <p className="text-red-600 text-sm text-center">{submitError}</p>
      ) : null}

      <div className="flex justify-end">
        <AsyncButton
          className="font-bold"
          isLoading={loading}
          loadingText="Agendando..."
          size="lg"
          type="button"
          variant="primary"
          onClick={onSubmit}
        >
          Confirmar y Agendar
        </AsyncButton>
      </div>
    </div>
  );
}

function SummaryRow({
  label,
  value,
}: {
  readonly label: string;
  readonly value: string;
}) {
  return (
    <div className="flex gap-2 text-sm">
      <span className="font-medium text-gray-600 min-w-[120px]">{label}:</span>
      <span className="text-gray-800">{value || "—"}</span>
    </div>
  );
}

// ─── Multi-step create form ───────────────────────────────────────────────────

interface MultiStepCreateFormProps {
  readonly initialForm: AppointmentRequest;
  readonly onSubmit: (
    form: AppointmentRequest,
  ) => Promise<ApiResponse<unknown | ValidationFailure[]>>;
  readonly onSuccess?: (appointmentId: number) => void;
}

function MultiStepCreateForm({
  initialForm,
  onSubmit,
  onSuccess,
}: MultiStepCreateFormProps) {
  const [searchParams] = useSearchParams();
  const followUp = searchParams.get("followUp") === "true";
  const parentConsultationId = searchParams.get("parentConsultationId");

  const [step, setStep] = useState(0);
  const [formState, setFormState] =
    useState<CreateFormState>(initialCreateState);
  const [stepErrors, setStepErrors] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [submitSuccess, setSubmitSuccess] = useState<boolean | null>(null);
  const [submitMessage, setSubmitMessage] = useState<string>("");

  // ── Selectors ──────────────────────────────────────────────────────────────

  const selectorSpecialty = useCallback(
    (item: SpecialtyResponse) => ({ label: item.name, value: String(item.id) }),
    [],
  );

  const selectorBranch = useCallback(
    (item: BranchResponse) => ({ label: item.name, value: String(item.id) }),
    [],
  );

  const selectorUser = useCallback(
    (item: UserResponse) => ({
      label: `${item.name} (${item.userName})`,
      value: String(item.id),
    }),
    [],
  );

  // ── Step validation ────────────────────────────────────────────────────────

  const validateStep = (currentStep: number): string | null => {
    if (currentStep === 0) {
      if (!formState.specialtyId) return "Debe seleccionar una especialidad.";
      if (!formState.branchId) return "Debe seleccionar una sucursal.";
    }
    if (currentStep === 1) {
      if (!formState.doctorId) return "Debe seleccionar un médico.";
      if (!formState.appointmentDate)
        return "Debe seleccionar una fecha y hora.";
      if (new Date(formState.appointmentDate) <= new Date()) {
        return "La fecha de la cita debe ser en el futuro.";
      }
    }
    if (currentStep === 2) {
      if (formState.reason.length < 10)
        return "El motivo debe tener al menos 10 caracteres.";
      if (formState.reason.length > 2000)
        return "El motivo no debe exceder 2000 caracteres.";
      if (formState.documentError) return formState.documentError;
    }
    return null;
  };

  const handleNext = () => {
    const error = validateStep(step);
    if (error) {
      setStepErrors(error);
      return;
    }
    setStepErrors(null);
    setStep((s) => s + 1);
  };

  const handleBack = () => {
    setStepErrors(null);
    setStep((s) => s - 1);
  };

  // ── Expiry handler ─────────────────────────────────────────────────────────

  const handleExpiry = useCallback(() => {
    setStep(0);
    setFormState(initialCreateState);
    setStepErrors(null);
  }, []);

  // ── Submit ─────────────────────────────────────────────────────────────────

  const handleSubmit = async () => {
    setLoading(true);
    setSubmitError(null);

    const request: AppointmentRequest = {
      ...initialForm,
      specialtyId: formState.specialtyId ? Number(formState.specialtyId) : null,
      branchId: formState.branchId ? Number(formState.branchId) : null,
      doctorId: formState.doctorId ? Number(formState.doctorId) : null,
      appointmentDate: formState.appointmentDate || null,
      reason: formState.reason,
      ...(followUp && {
        followUpType: 1,
        parentConsultationId: parentConsultationId
          ? Number(parentConsultationId)
          : null,
      }),
    };

    try {
      const response = await onSubmit(request);
      if (response.success) {
        setSubmitSuccess(true);
        setSubmitMessage(response.message ?? "Cita agendada correctamente");
        if (onSuccess) {
          const data = response.data as AppointmentResponse;
          onSuccess(data?.id ?? 0);
        }
      } else {
        setSubmitSuccess(false);
        setSubmitMessage(response.message ?? "Error al agendar la cita");
        setSubmitError(response.message ?? "Error al agendar la cita");
      }
    } catch {
      setSubmitSuccess(false);
      setSubmitError("Ocurrió un error inesperado. Intente de nuevo.");
    } finally {
      setLoading(false);
    }
  };

  // ── Render ─────────────────────────────────────────────────────────────────

  return (
    <div className="max-w-3xl mx-auto p-6">
      <h1 className="text-2xl font-bold text-center mb-6">Agendar Cita</h1>

      {submitSuccess != null && (
        <div className="mb-4">
          <Response message={submitMessage} type={submitSuccess} />
        </div>
      )}

      <StepForm
        currentStep={step}
        steps={STEP_LABELS}
        onBack={handleBack}
        onNext={handleNext}
      >
        {/* Step 1 — Especialidad y Sucursal */}
        {step === 0 && (
          <div className="flex flex-col gap-4">
            <CatalogueSelect<SpecialtyResponse>
              isRequired
              defaultValue={null}
              deps="State:eq:1"
              fieldSearch="Name"
              label="Especialidad"
              name="specialtyId"
              placeholder="Seleccione especialidad"
              queryFn={getSpecialties}
              selectorFn={selectorSpecialty}
              onChange={(opt) => {
                const o = opt as SingleValue<{ label: string; value: string }>;
                setFormState((prev) => ({
                  ...prev,
                  specialtyId: o?.value ?? null,
                  specialtyLabel: o?.label ?? "",
                }));
              }}
            />
            <CatalogueSelect<BranchResponse>
              isRequired
              defaultValue={null}
              deps="State:eq:1"
              fieldSearch="Name"
              label="Sucursal"
              name="branchId"
              placeholder="Seleccione sucursal"
              queryFn={getBranches}
              selectorFn={selectorBranch}
              onChange={(opt) => {
                const o = opt as SingleValue<{ label: string; value: string }>;
                setFormState((prev) => ({
                  ...prev,
                  branchId: o?.value ?? null,
                  branchLabel: o?.label ?? "",
                }));
              }}
            />
          </div>
        )}

        {/* Step 2 — Médico y Fecha */}
        {step === 1 && (
          <div className="flex flex-col gap-4">
            <CatalogueSelect<UserResponse>
              isRequired
              defaultValue={null}
              deps="State:eq:1"
              fieldSearch="Name"
              label="Médico"
              name="doctorId"
              placeholder="Buscar médico..."
              queryFn={getUsers}
              selectorFn={selectorUser}
              onChange={(opt) => {
                const o = opt as SingleValue<{ label: string; value: string }>;
                setFormState((prev) => ({
                  ...prev,
                  doctorId: o?.value ?? null,
                  doctorLabel: o?.label ?? "",
                  // Reset date when doctor changes
                  appointmentDate: "",
                }));
              }}
            />

            {formState.doctorId ? (
              <div className="flex flex-col gap-2">
                <label className="text-default-500 text-xs ms-1 font-medium">
                  Fecha y Hora de la Cita{" "}
                  <span className="text-danger font-bold ml-1">*</span>
                </label>
                <div className="rounded-xl border border-gray-200 bg-white p-4 dark:border-gray-700 dark:bg-gray-800">
                  <DynamicCalendar
                    doctorId={Number(formState.doctorId)}
                    onSlotSelected={(dateTime) => {
                      setFormState((prev) => ({
                        ...prev,
                        appointmentDate: dateTime.toISOString(),
                      }));
                    }}
                  />
                </div>
                {formState.appointmentDate ? (
                  <p className="text-sm text-green-600 font-medium ms-1">
                    <i className="bi bi-check-circle mr-1" />
                    Horario seleccionado:{" "}
                    {formatDateTimeLong(formState.appointmentDate)}
                  </p>
                ) : null}
              </div>
            ) : (
              <div className="rounded-xl border border-dashed border-gray-300 bg-gray-50 p-6 text-center text-sm text-gray-400 dark:border-gray-600 dark:bg-gray-800/50">
                <i className="bi bi-calendar-event text-2xl block mb-2" />
                Seleccione un médico para ver la disponibilidad de horarios
              </div>
            )}
          </div>
        )}

        {/* Step 3 — Motivo y Documento */}
        {step === 2 && (
          <div className="flex flex-col gap-4">
            <div className="flex flex-col gap-1">
              <label
                className="text-default-500 text-xs ms-1 font-medium"
                htmlFor="reason"
              >
                Motivo de Consulta (10–2000 caracteres){" "}
                <span className="text-danger font-bold ml-1">*</span>
              </label>
              <textarea
                className="w-full px-3 py-2 border rounded-md bg-default-100 hover:bg-default-200 transition-colors resize-y min-h-[100px]"
                id="reason"
                maxLength={2000}
                name="reason"
                placeholder="Describa el motivo de su consulta..."
                value={formState.reason}
                onChange={(e) => {
                  setFormState((prev) => ({ ...prev, reason: e.target.value }));
                }}
              />
              <p className="text-xs text-gray-400 text-right">
                {formState.reason.length}/2000
              </p>
            </div>

            <div className="flex flex-col gap-1">
              <label
                className="text-default-500 text-xs ms-1 font-medium"
                htmlFor="document"
              >
                Documento de referencia (PDF, máx. 2MB — opcional)
              </label>
              <input
                accept="application/pdf"
                className="w-full px-3 py-2 border rounded-md bg-default-100 hover:bg-default-200 transition-colors"
                id="document"
                name="document"
                type="file"
                onChange={(e) => {
                  const file = e.target.files?.[0] ?? null;
                  if (file) {
                    const error = validateDocument(file);
                    setFormState((prev) => ({
                      ...prev,
                      document: error ? null : file,
                      documentError: error,
                    }));
                  } else {
                    setFormState((prev) => ({
                      ...prev,
                      document: null,
                      documentError: null,
                    }));
                  }
                }}
              />
              {formState.documentError ? (
                <p className="text-danger text-sm ms-1">
                  {formState.documentError}
                </p>
              ) : null}
            </div>
          </div>
        )}

        {/* Step 4 — Confirmación */}
        {step === 3 && (
          <ConfirmationStep
            loading={loading}
            state={formState}
            submitError={submitError}
            onExpiry={handleExpiry}
            onSubmit={handleSubmit}
          />
        )}
      </StepForm>

      {/* Per-step validation error */}
      {stepErrors && step < 3 ? (
        <p className="mt-3 text-center text-sm text-red-600">{stepErrors}</p>
      ) : null}
    </div>
  );
}

