import { FieldError, Form, Input, Label, TextField } from "@heroui/react";
import { useCallback, type ChangeEvent } from "react";
import { useNavigate } from "react-router";
import { useForm } from "../../hooks/useForm";
import { useVitalSignAlerts } from "../../hooks/useVitalSignAlerts";
import type { ApiResponse } from "../../types/ApiResponse";
import type { ValidationFailure } from "../../types/ValidationFailure";
import type { VitalSignRequest } from "../../types/VitalSignResponse";
import { validateVitalSign } from "../../validations/vitalSignValidation";
import { AsyncButton } from "../button/AsyncButton";
import { Response } from "../messages/Response";
import { OptionsSelect, type OptionValue } from "../select/OptionsSelect";
import { VitalSignAlertsDisplay } from "../shared/VitalSignAlertsDisplay";

interface VitalSignFormProps {
  readonly type: "create" | "edit";
  readonly initialForm: VitalSignRequest;
  readonly onSubmit: (
    form: VitalSignRequest,
  ) => Promise<ApiResponse<unknown | ValidationFailure[]>>;
  /** When true, appointmentId and nurseId are pre-filled and hidden */
  readonly fromNurseDashboard?: boolean;
  /** Patient name to display as context header */
  readonly patientName?: string;
}

export function VitalSignForm({
  type,
  initialForm,
  onSubmit,
  fromNurseDashboard = false,
  patientName,
}: VitalSignFormProps) {
  const isEditing = type === "edit";
  const navigate = useNavigate();

  const {
    form,
    errors,
    handleChange,
    handleSubmit,
    success,
    message,
    loading,
  } = useForm<VitalSignRequest, unknown>(
    initialForm,
    validateVitalSign,
    onSubmit,
    true,
  );

  const alerts = useVitalSignAlerts({
    bloodPressureSystolic: form.bloodPressureSystolic
      ? Number(form.bloodPressureSystolic)
      : null,
    bloodPressureDiastolic: form.bloodPressureDiastolic
      ? Number(form.bloodPressureDiastolic)
      : null,
    temperature: form.temperature ? Number(form.temperature) : null,
    heartRate: form.heartRate ? Number(form.heartRate) : null,
  });

  const handleTextChange = useCallback(
    (name: string) => (val: string) => {
      handleChange({
        target: { name, value: val },
      } as unknown as ChangeEvent<HTMLInputElement>);
    },
    [handleChange],
  );

  const handleStateChange = useCallback(
    (newValue: OptionValue) => {
      const value =
        newValue && !Array.isArray(newValue) && "value" in newValue
          ? Number((newValue as { value: string }).value)
          : null;
      handleChange({
        target: { name: "state", value },
      } as unknown as ChangeEvent<HTMLInputElement>);
    },
    [handleChange],
  );

  return (
    <div className="max-w-3xl mx-auto p-6">
      <h1 className="text-2xl font-bold text-center mb-2">
        {isEditing ? "Editar Signos Vitales" : "Registrar Signos Vitales"}
      </h1>
      {fromNurseDashboard && patientName ? (
        <div className="mb-4 rounded-xl bg-blue-50 border border-blue-200 px-4 py-3 text-center dark:bg-blue-900/20 dark:border-blue-700">
          <p className="text-sm text-blue-700 dark:text-blue-300">
            <i className="bi bi-person-check mr-2" />
            Registrando signos vitales para: <strong>{patientName}</strong>
          </p>
          <p className="text-xs text-blue-500 mt-0.5">
            Cita #{initialForm.appointmentId}
          </p>
        </div>
      ) : null}
      {success != null && <Response message={message} type={success} />}
      <Form
        className="flex flex-col gap-4"
        validationErrors={errors}
        onSubmit={handleSubmit}
      >
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {/* Only show manual ID fields when NOT coming from nurse dashboard */}
          {!fromNurseDashboard && (
            <>
              <TextField
                isRequired
                className="w-full flex flex-col gap-1"
                isInvalid={!!errors?.appointmentId}
                name="appointmentId"
                onChange={handleTextChange("appointmentId")}
              >
                <Label className="font-bold">ID de Cita</Label>
                <Input
                  className="w-full px-3 py-2 border rounded-md"
                  type="number"
                  value={form.appointmentId?.toString() || ""}
                />
                {errors?.appointmentId ? (
                  <FieldError>{errors.appointmentId as string}</FieldError>
                ) : null}
              </TextField>
              <TextField
                isRequired
                className="w-full flex flex-col gap-1"
                isInvalid={!!errors?.nurseId}
                name="nurseId"
                onChange={handleTextChange("nurseId")}
              >
                <Label className="font-bold">ID Enfermero/a</Label>
                <Input
                  className="w-full px-3 py-2 border rounded-md"
                  type="number"
                  value={form.nurseId?.toString() || ""}
                />
                {errors?.nurseId ? (
                  <FieldError>{errors.nurseId as string}</FieldError>
                ) : null}
              </TextField>
            </>
          )}

          <div className="md:col-span-2">
            <p className="text-sm font-semibold text-gray-600 mb-2">
              Presión Arterial
            </p>
            <div className="grid grid-cols-2 gap-4">
              <TextField
                isRequired
                className="w-full flex flex-col gap-1"
                isInvalid={!!errors?.bloodPressureSystolic}
                name="bloodPressureSystolic"
                onChange={handleTextChange("bloodPressureSystolic")}
              >
                <Label className="font-bold">Sistólica (mmHg)</Label>
                <Input
                  className="w-full px-3 py-2 border rounded-md"
                  max="250"
                  min="60"
                  type="number"
                  value={form.bloodPressureSystolic?.toString() || ""}
                />
                {errors?.bloodPressureSystolic ? (
                  <FieldError>
                    {errors.bloodPressureSystolic as string}
                  </FieldError>
                ) : null}
              </TextField>
              <TextField
                isRequired
                className="w-full flex flex-col gap-1"
                isInvalid={!!errors?.bloodPressureDiastolic}
                name="bloodPressureDiastolic"
                onChange={handleTextChange("bloodPressureDiastolic")}
              >
                <Label className="font-bold">Diastólica (mmHg)</Label>
                <Input
                  className="w-full px-3 py-2 border rounded-md"
                  max="150"
                  min="40"
                  type="number"
                  value={form.bloodPressureDiastolic?.toString() || ""}
                />
                {errors?.bloodPressureDiastolic ? (
                  <FieldError>
                    {errors.bloodPressureDiastolic as string}
                  </FieldError>
                ) : null}
              </TextField>
            </div>
          </div>

          <TextField
            isRequired
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.temperature}
            name="temperature"
            onChange={handleTextChange("temperature")}
          >
            <Label className="font-bold">Temperatura (°C)</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              max="42"
              min="34"
              step="0.1"
              type="number"
              value={form.temperature?.toString() || ""}
            />
            {errors?.temperature ? (
              <FieldError>{errors.temperature as string}</FieldError>
            ) : null}
          </TextField>

          <TextField
            isRequired
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.heartRate}
            name="heartRate"
            onChange={handleTextChange("heartRate")}
          >
            <Label className="font-bold">Frecuencia Cardíaca (bpm)</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              max="220"
              min="30"
              type="number"
              value={form.heartRate?.toString() || ""}
            />
            {errors?.heartRate ? (
              <FieldError>{errors.heartRate as string}</FieldError>
            ) : null}
          </TextField>

          <TextField
            isRequired
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.weight}
            name="weight"
            onChange={handleTextChange("weight")}
          >
            <Label className="font-bold">Peso (kg)</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              max="300"
              min="0.5"
              step="0.01"
              type="number"
              value={form.weight?.toString() || ""}
            />
            {errors?.weight ? (
              <FieldError>{errors.weight as string}</FieldError>
            ) : null}
          </TextField>

          <TextField
            isRequired
            className="w-full flex flex-col gap-1"
            isInvalid={!!errors?.height}
            name="height"
            onChange={handleTextChange("height")}
          >
            <Label className="font-bold">Altura (cm)</Label>
            <Input
              className="w-full px-3 py-2 border rounded-md"
              max="250"
              min="30"
              step="0.01"
              type="number"
              value={form.height?.toString() || ""}
            />
            {errors?.height ? (
              <FieldError>{errors.height as string}</FieldError>
            ) : null}
          </TextField>

          <OptionsSelect
            defaultValue={
              form.isEmergency
                ? { label: "Sí 🚨", value: "true" }
                : { label: "No", value: "false" }
            }
            label="¿Emergencia?"
            name="isEmergency"
            options={[
              { label: "No", value: "false" },
              { label: "Sí 🚨", value: "true" },
            ]}
            placeholder="Seleccione"
            onChange={(v) => {
              const val =
                v && !Array.isArray(v) && "value" in v
                  ? (v as { value: string }).value === "true"
                  : false;
              handleChange({
                target: { name: "isEmergency", value: val },
              } as unknown as ChangeEvent<HTMLInputElement>);
            }}
          />

          <OptionsSelect
            isRequired
            defaultValue={
              form.state !== null && form.state !== undefined
                ? {
                    label: form.state === 1 ? "Activo" : "Inactivo",
                    value: String(form.state),
                  }
                : { label: "Activo", value: "1" }
            }
            errorMessage={errors?.state as string}
            isInvalid={!!errors?.state}
            label="Estado"
            name="state"
            options={[
              { label: "Activo", value: "1" },
              { label: "Inactivo", value: "0" },
            ]}
            placeholder="Seleccione un estado"
            onChange={handleStateChange}
          />
        </div>
        <VitalSignAlertsDisplay alerts={alerts} />
        <div className="flex gap-4 justify-end mt-4">
          <AsyncButton
            className="font-bold"
            isLoading={false}
            size="lg"
            type="button"
            variant="secondary"
            onClick={() =>
              navigate(fromNurseDashboard ? "/nurse-dashboard" : "/vital-sign")
            }
          >
            Cancelar
          </AsyncButton>
          <AsyncButton
            className="font-bold"
            isLoading={loading}
            loadingText={isEditing ? "Actualizando..." : "Registrando..."}
            size="lg"
            type="submit"
            variant="primary"
          >
            {isEditing ? "Actualizar" : "Registrar Signos Vitales"}
          </AsyncButton>
        </div>
      </Form>
    </div>
  );
}

import { Button } from "@heroui/react";
import { useTheme } from "next-themes";
import { useCallback, useEffect, useRef, useState } from "react";
import { api } from "../../configs/axios/interceptors";
import { useAuth } from "../../hooks/useAuth";
import { getTimezones } from "../../services/timezoneService";
import { useAuthStore } from "../../stores/useAuthStore";
import type { ApiResponse } from "../../types/ApiResponse";
import type { TimezoneResponse } from "../../types/TimezoneResponse";
import { getAppTimezone } from "../../utils/dateFormatter";

interface HeaderProps {
  readonly toggleSidebar: () => void;
}

export function Header({ toggleSidebar }: HeaderProps) {
  const { setTheme, resolvedTheme } = useTheme();
  const { name } = useAuth();
  const signIn = useAuthStore((s) => s.signIn);
  const authState = useAuthStore((s) => s.authState);
  const [mounted, setMounted] = useState(false);

  // Timezone dropdown state
  const [tzOpen, setTzOpen] = useState(false);
  const [timezones, setTimezones] = useState<TimezoneResponse[]>([]);
  const [tzLoading, setTzLoading] = useState(false);
  const [tzLoaded, setTzLoaded] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const currentTz = getAppTimezone();
  // Show short label like "UTC-6" from the IANA id
  const tzShort = currentTz.split("/").pop()?.replace(/_/g, " ") ?? currentTz;

  useEffect(() => {
    setMounted(true);
  }, []);

  // Close dropdown on outside click
  useEffect(() => {
    if (!tzOpen) return;
    const handler = (e: MouseEvent) => {
      if (
        dropdownRef.current &&
        !dropdownRef.current.contains(e.target as Node)
      ) {
        setTzOpen(false);
      }
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [tzOpen]);

  // Load timezones on first open
  const handleTzToggle = useCallback(async () => {
    setTzOpen((prev) => !prev);
    if (!tzLoaded) {
      setTzLoading(true);
      try {
        const res = await getTimezones({
          filters: "State:eq:1",
          include: null,
          includeTotal: false,
          pageNumber: 1,
          pageSize: 100,
        });
        if (res.success) setTimezones(res.data);
        setTzLoaded(true);
      } catch {
        /* silent */
      } finally {
        setTzLoading(false);
      }
    }
  }, [tzLoaded]);

  const handleTzSelect = useCallback(
    async (tz: TimezoneResponse) => {
      setTzOpen(false);
      try {
        const res = await api.patch<
          unknown,
          ApiResponse<{ timezoneIanaId: string }>,
          { timezoneId: number }
        >("/Auth/Timezone", { timezoneId: tz.id });
        if (res.success) {
          signIn({ ...authState, timezoneIanaId: tz.ianaId });
          window.location.reload();
        }
      } catch {
        /* silent */
      }
    },
    [signIn, authState],
  );

  const handleThemeChange = useCallback(() => {
    setTheme(resolvedTheme === "dark" ? "light" : "dark");
  }, [setTheme, resolvedTheme]);

  return (
    <header className="relative sticky top-0 z-40 flex h-16 w-full items-center justify-between border-b border-[var(--color-border)] bg-[rgba(255,255,255,0.85)] dark:bg-[rgba(24,24,27,0.85)] px-4 backdrop-blur-md transition-colors duration-300">
      <Button
        aria-label="Toggle Sidebar"
        className="flex min-w-0 bg-transparent items-center justify-center rounded-md p-2 text-gray-600 hover:bg-[var(--color-surface-100)] dark:text-gray-300 transition-colors"
        onClick={toggleSidebar}
      >
        <i className="bi bi-list text-2xl" />
      </Button>

      <div className="flex items-center gap-2 sm:gap-3">
        {/* Timezone selector */}
        <div ref={dropdownRef} className="relative">
          <button
            className="flex items-center gap-1.5 px-2 py-1.5 rounded-lg text-xs font-medium text-gray-600 dark:text-gray-300 hover:bg-[var(--color-surface-100)] transition-colors"
            title={`Zona horaria: ${currentTz}`}
            type="button"
            onClick={handleTzToggle}
          >
            <i className="bi bi-globe text-sm text-blue-500" />
            <span className="hidden sm:inline max-w-[100px] truncate">
              {tzShort}
            </span>
            <i
              className={`bi bi-chevron-${tzOpen ? "up" : "down"} text-[10px]`}
            />
          </button>

          {tzOpen ? (
            <div className="absolute right-0 top-full mt-1 w-72 max-h-80 overflow-auto bg-white dark:bg-zinc-800 border border-gray-200 dark:border-zinc-700 rounded-xl shadow-xl z-50">
              <div className="p-2 border-b border-gray-100 dark:border-zinc-700">
                <p className="text-xs font-semibold text-gray-500 dark:text-gray-400 px-2">
                  Zona Horaria
                </p>
              </div>
              {tzLoading ? (
                <div className="p-4 text-center text-sm text-gray-400">
                  <i className="bi bi-hourglass-split animate-spin mr-1" />
                  Cargando...
                </div>
              ) : (
                <div className="py-1">
                  {timezones.map((tz) => (
                    <button
                      key={tz.id}
                      className={`w-full text-left px-3 py-2 text-sm transition-colors ${
                        tz.ianaId === currentTz
                          ? "bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 font-medium"
                          : "text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-zinc-700"
                      }`}
                      type="button"
                      onClick={() => handleTzSelect(tz)}
                    >
                      <span className="block truncate">{tz.displayName}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
          ) : null}
        </div>

        {/* User name */}
        {name ? (
          <span className="hidden sm:flex items-center gap-2 text-sm font-medium text-gray-700 dark:text-gray-300">
            <i className="bi bi-person-circle text-blue-600" />
            <span className="max-w-[140px] truncate">{name}</span>
          </span>
        ) : null}

        {/* Theme toggle */}
        {mounted ? (
          <Button
            aria-label="Alternar tema"
            className="theme-toggle-btn flex h-10 w-10 min-w-0 items-center justify-center rounded-full bg-[var(--color-surface-100)] text-[var(--color-primary)] transition-colors"
            onClick={handleThemeChange}
          >
            {resolvedTheme === "dark" ? (
              <i className="bi bi-sun-fill text-lg" />
