              <i className="bi bi-moon-stars-fill text-lg" />
            )}
          </Button>
        ) : null}
      </div>
      <div className="header-accent-line" />
    </header>
  );
}

import { Button, Modal } from "@heroui/react";
import { Icon } from "../icons/Icon";

interface ConfirmDialogProps {
